package com.opensocket.aievent.database.persistence.a2a.repository;
import java.time.OffsetDateTime; import java.time.temporal.ChronoUnit; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.transaction.annotation.Transactional; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2ARateLimitRepository implements A2ARateLimitRepository { private final A2ARateLimitDao dao; public MybatisA2ARateLimitRepository(A2ARateLimitDao d){dao=d;} @Transactional public boolean tryAcquire(String t,String p,int limit,OffsetDateTime now){OffsetDateTime w=now.truncatedTo(ChronoUnit.MINUTES);dao.increment(t,p,w);Integer n=dao.count(t,p,w);return n!=null&&n<=Math.max(1,limit);} public String mode(){return "MYBATIS";} }
